27:/** An ATS host family and the posting id inside its URL. */
28:export interface PostingIdentity {
29:  /** Which board host family — ids are only comparable within one. */
30:  family: string;
31:  /** The posting id as the URL spells it. */
32:  id: string;
33:  /**
34:   * The company's board slug, when the URL carries one — what the ATS APIs key
35:   * on (`/v1/boards/<board>/jobs/<id>`).
36:   *
37:   * Null on an embedded form, where `gh_jid` names the posting but nothing
38:   * names the board. A null board means the liveness probe cannot ask, and
39:   * "cannot ask" is `unknown`, never `dead`.
40:   */
41:  board: string | null;
42:}
43:
44:/**
45: * The board slug is the first path segment, minus the ones that are API
46: * scaffolding rather than a company.
47: *
48: * Deliberately duplicated from `parseAtsBoard` (@fbj/adapters `ats/board.ts`),
49: * which answers the same question for a different purpose — registering a whole
50: * board as a discovery source. `core` sits below `adapters`, so importing it
51: * would invert the layering for fifteen lines; this file already duplicates the
52: * host regexes for the same reason.
53: */
54:function firstSegment(
55:  path: string,
56:  skip: readonly string[] = [],
57:): string | null {
58:  for (const part of path.split("/")) {
59:    if (!part) continue;
60:    if (skip.includes(part.toLowerCase())) continue;
61:    return part;
62:  }
63:  return null;
64:}
65:
66:/**
67: * Read the posting id out of an apply URL, or null when the URL does not carry
68: * one.
69: *
70: * Null is the common case and must stay cheap: a company career page, a
71: * redirect through a tracker, a multi-step form with a session token. Those are
72: * compared by nothing, which is correct — this only ever answers "these two
73: * URLs name DIFFERENT postings", never "these are the same one".
74: */
75:export function postingIdentity(
76:  url: string | null | undefined,
77:): PostingIdentity | null {
78:  if (!url) return null;
79:  let u: URL;
80:  try {
81:    u = new URL(url.trim());
82:  } catch {
83:    return null;
84:  }
85:  const host = u.host.toLowerCase();
86:  const path = u.pathname;
87:
88:  // Greenhouse: /<token>/jobs/<id>, and boards-api /v1/boards/<token>/jobs/<id>
89:  if (/(^|\.)boards(-api)?\.greenhouse\.io$/.test(host)) {
90:    const m = /\/jobs\/(\d+)/.exec(path);
91:    if (!m) return null;
92:    return {
93:      family: "greenhouse",
94:      id: m[1]!,
95:      board: firstSegment(path, ["v1", "boards", "jobs"]),
96:    };
97:  }
98:  // Greenhouse embedded on a company domain carries the id as `gh_jid` — the
99:  // posting, but never the board.
100:  const ghJid = u.searchParams.get("gh_jid");
101:  if (ghJid) return { family: "greenhouse", id: ghJid, board: null };
102:
103:  // Lever: /<token>/<uuid>
104:  if (/(^|\.)lever\.co$/.test(host)) {
105:    const m = /\/[^/]+\/([0-9a-f-]{8,})/i.exec(path);
106:    if (!m) return null;
107:    return {
108:      family: "lever",
109:      id: m[1]!.toLowerCase(),
110:      board: firstSegment(path, ["v0", "postings"]),
111:    };
112:  }
113:  // Ashby: /<token>/<uuid>
114:  if (/(^|\.)ashbyhq\.com$/.test(host)) {
115:    const m = /\/[^/]+\/([0-9a-f-]{8,})/i.exec(path);
116:    if (!m) return null;
117:    return {
118:      family: "ashby",
119:      id: m[1]!.toLowerCase(),
120:      board: firstSegment(path, ["posting-api", "job-board"]),
121:    };
122:  }
123:  // Workable: /<token>/j/<CODE>/
124:  if (/(^|\.)workable\.com$/.test(host)) {
125:    const m = /\/j\/([0-9A-Z]{6,})/i.exec(path);
126:    if (!m) return null;
127:    return {
128:      family: "workable",
129:      id: m[1]!.toUpperCase(),
130:      board: firstSegment(path),
131:    };
132:  }
133:  // SmartRecruiters: /<company>/<numeric-id>-<slug>
134:  if (/(^|\.)smartrecruiters\.com$/.test(host)) {
135:    const m = /\/(\d{9,})/.exec(path);
136:    if (!m) return null;
137:    return {
138:      family: "smartrecruiters",
139:      id: m[1]!,
140:      board: firstSegment(path, ["v1", "companies", "postings"]),
141:    };
142:  }
143:  return null;
